import{_ as t,o,c as d,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"UI/UX Wireframes, Design System & Frontend Architecture (docs/wireframe/)","description":"","frontmatter":{},"headers":[],"relativePath":"wireframe/README.md","filePath":"wireframe/README.md"}'),a={name:"wireframe/README.md"};function r(i,e,n,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="ui-ux-wireframes-design-system-frontend-architecture-docs-wireframe" tabindex="-1">UI/UX Wireframes, Design System &amp; Frontend Architecture (<code>docs/wireframe/</code>) <a class="header-anchor" href="#ui-ux-wireframes-design-system-frontend-architecture-docs-wireframe" aria-label="Permalink to &quot;UI/UX Wireframes, Design System &amp; Frontend Architecture (`docs/wireframe/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../ba/README.html">BA Specifications</a> · <a href="./../screenshots/README.html">UI Screenshots (<code>D15</code>–<code>D19</code>)</a> · <a href="./../archive/v1-legacy/README.html">V1 Legacy Wireframe Archive</a></p><p>This directory contains BrandHub&#39;s <strong>V2/V3 UI/UX wireframe architecture and frontend implementation checklist</strong> aligned with the production <code>brandhub-web</code> (<code>React 19.2</code> + <code>Vite 8.3</code> + <code>Tailwind CSS 4.3</code>) and <code>brandhub-mobile-app</code> (<code>Expo SDK 58</code> + <code>React Native 0.88</code>) applications across Desktop (<code>1440px</code>) and Mobile (<code>375px</code>) viewports.</p><hr><h2 id="_1-authoritative-v2-v3-specifications" tabindex="-1">1. Authoritative V2/V3 Specifications <a class="header-anchor" href="#_1-authoritative-v2-v3-specifications" aria-label="Permalink to &quot;1. Authoritative V2/V3 Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Document</th><th style="text-align:left;">Scope</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./wireframe-blueprint.html">wireframe-blueprint.md</a></td><td style="text-align:left;"><strong>Primary V2/V3 Wireframe &amp; Solutions Architecture Blueprint</strong>: 11 core screen layouts (<code>Login/Auth</code>, <code>Agency Directory &amp; Dashboard</code>, <code>Workspace Dashboard &amp; Personal Launchpad</code>, <code>Package/Campaign Negotiation &amp; Timeline</code>, <code>4-View Task Board</code>, <code>Multi-Section Content &amp; AI Studio Editor</code>, <code>Content Calendar</code>, <code>Client Portal</code>, <code>Collaborator Directory</code>, <code>Analytics</code>, <code>Admin Console</code>) strictly enforcing the <strong>6 Canonical Roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>) and <strong>4 social platforms</strong> (<strong>Facebook, Instagram, TikTok, Threads</strong>).</td></tr><tr><td style="text-align:left;"><a href="./wireframe-to-code-checklist.html">wireframe-to-code-checklist.md</a></td><td style="text-align:left;"><strong>Wireframe-to-Code Engineering Checklist</strong>: 8-stage implementation contract covering <code>shadcn/ui</code> (<code>v4.13</code>) + Radix UI + <code>@astryxdesign/core</code> primitives, workspace-scoped RBAC (<code>useWorkspaceRole</code>), collaborative TipTap <code>3.35</code> + Yjs <code>13.6</code> editing, STOMP WebSockets, Agora voice/video calls, bilingual <code>i18next</code> (<code>vi</code>/<code>en</code>), and Light/Dark semantic tokens.</td></tr></tbody></table><hr><h2 id="_2-production-frontend-stack-snapshot-brandhub-web-brandhub-mobile-app" tabindex="-1">2. Production Frontend Stack Snapshot (<code>brandhub-web</code> &amp; <code>brandhub-mobile-app</code>) <a class="header-anchor" href="#_2-production-frontend-stack-snapshot-brandhub-web-brandhub-mobile-app" aria-label="Permalink to &quot;2. Production Frontend Stack Snapshot (`brandhub-web` &amp; `brandhub-mobile-app`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;"><code>brandhub-web</code> (Web Dashboard <code>:5173</code>)</th><th style="text-align:left;"><code>brandhub-mobile-app</code> (Companion App <code>:8090</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Core Runtime &amp; Bundler</strong></td><td style="text-align:left;">React <code>19.2.6</code>, TypeScript <code>6.0.2</code>, Vite <code>8.3.8</code>, React Router <code>7.16.0</code></td><td style="text-align:left;">Expo SDK <code>~58.0.26</code>, React Native <code>0.88.1</code>, React <code>19.3.0</code>, TypeScript <code>6.0.3</code></td></tr><tr><td style="text-align:left;"><strong>Styling &amp; Design System</strong></td><td style="text-align:left;">Tailwind CSS <code>4.3.0</code> (<code>@tailwindcss/vite</code>), <code>shadcn</code> <code>4.13.0</code>, <code>radix-ui</code> <code>1.6.2</code>, <code>@astryxdesign/core</code> <code>0.7.16</code>, <code>lucide-react</code> <code>1.17.0</code></td><td style="text-align:left;">Native StyleSheet + Reanimated <code>4.7.1</code>, Gesture Handler <code>3.3.0</code>, <code>lucide-react-native</code> <code>1.62.0</code>, <code>expo-image</code></td></tr><tr><td style="text-align:left;"><strong>State &amp; Server Cache</strong></td><td style="text-align:left;">TanStack Query <code>5.100.14</code>, Zustand <code>5.0.14</code> + Immer <code>11.1.15</code>, React Hook Form <code>7.77.0</code> + Zod <code>4.4.3</code></td><td style="text-align:left;">Zustand <code>5.0.14</code>, <code>expo-secure-store</code> (RS256 token storage), <code>expo-auth-session</code></td></tr><tr><td style="text-align:left;"><strong>Rich Editing &amp; Realtime</strong></td><td style="text-align:left;">TipTap <code>3.35.0</code> + Yjs <code>13.6.33</code> CRDT, <code>@stomp/stompjs</code> <code>7.3.0</code> WebSockets, Agora RTC <code>4.24.9</code></td><td style="text-align:left;">Yjs <code>13.6.33</code> (<code>y-protocols</code>), <code>expo-notifications</code> (FCM push), <code>react-native-vision-camera</code> <code>5.2.4</code></td></tr><tr><td style="text-align:left;"><strong>Scheduling, Charts &amp; Motion</strong></td><td style="text-align:left;">FullCalendar <code>6.1.21</code> (<code>daygrid</code>/<code>timegrid</code>/<code>interaction</code>), Recharts <code>3.10.1</code>, Motion <code>12.43.0</code> + GSAP <code>3.15.0</code>, <code>qrcode.react</code> <code>4.2.0</code> (SePay VietQR &amp; 2FA TOTP)</td><td style="text-align:left;"><code>react-native-qrcode-svg</code>, <code>expo-video</code>, <code>expo-local-authentication</code></td></tr><tr><td style="text-align:left;"><strong>Internationalization &amp; QA</strong></td><td style="text-align:left;"><code>i18next</code> <code>26.3.6</code> + <code>react-i18next</code> <code>17.0.11</code> (<code>vi.json</code> + <code>en.json</code> parity), Playwright <code>1.62.1</code> + Vitest <code>3.2.4</code></td><td style="text-align:left;">Bilingual locale dictionaries, Jest <code>30.5.2</code> + <code>@testing-library/react-native</code> <code>14.1.0</code></td></tr></tbody></table><hr><h2 id="_3-historical-v1-prototype-deliverables-archived" tabindex="-1">3. Historical V1 Prototype Deliverables (Archived) <a class="header-anchor" href="#_3-historical-v1-prototype-deliverables-archived" aria-label="Permalink to &quot;3. Historical V1 Prototype Deliverables (Archived)&quot;">​</a></h2><p>Early V1 Figma task reports from the legacy <code>Uibrandhubs</code> prototype (<code>DA-E08-01</code> 7-screen overview, <code>DA-E08-02</code> initial token report, <code>DA-E08-03</code> V1 user flows, and <code>install-animate-report.md</code>) have been consolidated into the <a href="./../archive/v1-legacy/README.html">V1 Legacy Archive</a> so <code>docs/wireframe/</code> contains only active V2/V3 architecture documents.</p>',12)])])}const g=t(a,[["render",r]]);export{m as __pageData,g as default};
